<?php
require_once 'functions.php';require_login();$error='';$success='';if($_SERVER['REQUEST_METHOD']==='POST'){$reason=trim($_POST['reason']??'');$type=$_POST['target_type']??'other';if(!in_array($type,['user','message','news','other'],true)||mb_strlen($reason)<8||mb_strlen($reason)>1000){$error='Décris le problème en 8 à 1 000 caractères.';}else{$q=$pdo->prepare('INSERT INTO reports(reporter_id,target_type,target_id,reason) VALUES(?,?,?,?)');$q->execute([$_SESSION['user_id'],$type,($_POST['target_id']??'')!==''?(int)$_POST['target_id']:null,$reason]);$success='Signalement transmis à la modération.';}}page_header('Signaler un contenu'); ?><section class="page-intro"><div class="eyebrow">SÉCURITÉ</div><h1>Signaler un contenu</h1><p>Explique clairement ce qui pose problème. Évite de transmettre des données privées inutiles.</p></section><?php if($error): ?><div class="notice error"><?= e($error) ?></div><?php endif; ?><?php if($success): ?><div class="notice"><?= e($success) ?></div><?php endif; ?><form class="panel form-panel" method="post"><label>Type de signalement<select name="target_type"><option value="other">Autre</option><option value="user">Profil</option><option value="message">Message</option><option value="news">Actualité</option></select></label><label>ID du contenu (facultatif)<input type="number" min="1" name="target_id"></label><label>Explication<textarea name="reason" maxlength="1000" required></textarea></label><button class="button" type="submit">Envoyer le signalement</button></form><?php page_footer(); ?>